    bg=Counter(c for row in gi for c in row).most_common(1)[0][0]
    cnt=Counter(c for row in gi for c in row)
    # marker color: a color forming a thin diagonal (small count, not band)
    mc=None
    for val,v in cnt.items():
        if v>=3 and 3<=v<=max(H,W)*2:
            cells=[(r,c) for r in range(H) for c in range(W) if gi[r][c]==val]
            if len(set(r-c for r,c in cells))==1 or len(set(r+c for r,c in cells))==1:
