        p=base; path=[]
        while True:
            q=(p[0]+d[0],p[1]+d[1])
            if not(0<=q[0]<H and 0<=q[1]<W): return 'edge',path,q
            if gi[q[0]][q[1]]!=bg: return 'barrier',path,q
            path.append(q); p=q
    cands=[]
    for nm,d in [('down-right',(1,1)),('up-left',(-1,-1))]:
        if d==(1,1): base=max(s,key=lambda p:(p[0],p[1]))
