def f(gi, verbose=False):
    g=[row[:] for row in gi]; H=len(g); W=len(g[0])
    bg=Counter(c for row in g for c in row).most_common(1)[0][0]
    cnt=Counter(c for row in g for c in row)
    mc=None; diag=None
    for val,v in cnt.items():
        if 3<=v and v<=2*(H+W)//5:
            cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==val]
            if len(set(r-c for r,c in cells))==1 or len(set(r+c for r,c in cells))==1:
                mc=val; diag=cells; break
    s=set(diag)
    # travel dir: the one whose forward ray soon meets a barrier (in bounds non-bg) before exiting
    def rayinfo(d):
        base=max(s,key=lambda p:p[0]*d[0]+p[1]*d[1]) if d==(1,1) else min(s,key=lambda p:p[0]*d[0]+p[1]*d[1])
