def run(gi,g=None,verbose=False):
    gi=[row[:] for row in gi] if g is None else g
    H=len(gi); W=len(gi[0])
    bg=Counter(c for row in gi for c in row).most_common(1)[0][0]
    cnt=Counter(c for row in gi for c in row)
    mc=None; diag=None
    for val,v in sorted(cnt.items()):
        cells=[(r,c) for r in range(H) for c in range(W) if gi[r][c]==val]
        if len(set(r-c for r,c in cells))==1 or len(set(r+c for r,c in cells))==1:
            if verbose: print('marker',val,len(cells))
            mc=val; diag=cells; break
    s=set(diag)
    def run_dir(d):
        # walk from extreme marker cell along d, through same-color marker cells allowed,
        # painting bg cells; stop at different color / out
        base=max(s,key=lambda p:p[0]*d[0]+p[1]*d[1]) if d==(1,1) else min(s,key=lambda p:p[0]*d[0]+p[1]*d[1])
        p=base; path=[]; hit=None
        while True:
            q=(p[0]+d[0],p[1]+d[1])
            if not(0<=q[0]<H and 0<=q[1]<W): return ('E',None,path,p,d)
            if gi[q[0]][q[1]]==mc:
                p=q; continue
            if gi[q[0]][q[1]]!=bg:
                return ('B',q,path,p,d)
            path.append(q); p=q
    return bg,mc,diag,(run_dir((1,1)),run_dir((-1,-1)))
